def fill(text):
    return (text.replace('%(lane)s', LANE).replace('%(pkg)s', PKG).replace('%(c1)s', C1)
            .replace('%(c2)s', C2).replace('%(freeze)s', FREEZE).replace('%(base)s', BASE))


def build(wave, report_dir, items):
    return {
        "wave": "round-45-%s" % wave,
        "reportDir": report_dir,
        "template": TEMPLATE,
        "context": COMMON,
        "items": [
            {"name": n, "role": r, "axes": a, "milestone": m, "item": fill(t)}
            for n, r, a, m, t in items
        ],
    }


def main():
    wave = sys.argv[1] if len(sys.argv) > 1 else 'w1'
    items = {'w1': W1, 'w2': W2}[wave]
    spec = build(wave, '.ufo/waves/round-45/%s' % wave, items)
    out = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'spec-%s.json' % wave)
    with open(out, 'w', encoding='utf-8') as handle:
        json.dump(spec, handle, indent=2, ensure_ascii=False)
    roles = {}
    for it in spec['items']:
        roles[it['role']] = roles.get(it['role'], 0) + 1
    print('wrote %s with %d items %s' % (out, len(items), json.dumps(roles, sort_keys=True)))


if __name__ == '__main__':
    main()
